function v8_recalcular_custos(PDO $pdo,int $osId):void{$st=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN tipo='MAO_OBRA' THEN valor ELSE 0 END),0) mao,COALESCE(SUM(CASE WHEN tipo<>'MAO_OBRA' THEN valor ELSE 0 END),0) terceiros FROM os_custos_documentos WHERE ordem_servico_id=?");$st->execute([$osId]);$r=$st->fetch(PDO::FETCH_ASSOC)?:['mao'=>0,'terceiros'=>0];$pdo->prepare("UPDATE ordens_servico SET custo_mao_obra=?,custo_terceiros=? WHERE id=?")->execute([$r['mao'],$r['terceiros'],$osId]);geop_v8_update_financial_total($pdo,$osId);}
